<?php
namespace App\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
class AuthController extends Controller{public function create(){return view('login');}public function store(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']);if(Auth::attempt($c,$r->boolean('remember'))){$r->session()->regenerate();return redirect()->route('dashboard');}return back()->withErrors(['email'=>'Email atau password salah.']);}public function destroy(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');}}
